import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/schueler/svws-kataloge-raeume-json.png",m=JSON.parse('{"title":"JSON-Dateien lesen und verstehen","description":"","frontmatter":{"title":"JSON-Dateien lesen und verstehen","source_pageid":1414,"source_revision":5634},"headers":[],"relativePath":"schild3/schueler/das-json-dateiformat-tutorial.md","filePath":"schild3/schueler/das-json-dateiformat-tutorial.md"}'),o={name:"schild3/schueler/das-json-dateiformat-tutorial.md"};function a(l,e,d,u,h,c){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="json-dateien-lesen-und-verstehen" tabindex="-1">JSON-Dateien lesen und verstehen <a class="header-anchor" href="#json-dateien-lesen-und-verstehen" aria-label="Permalink to &quot;JSON-Dateien lesen und verstehen&quot;">​</a></h1><p>Lernen Sie die grundlegenden Elemente des JSON-Formats kennen, das unter anderem für Notendateien verwendet wird. Die Beispiele erläutern Werte, Zeichenketten, Arrays und verschachtelte Objekte.</p><p>Der SVWS-Server und SVWS-Client und damit auch Teile von SchILD-NRW nutzen die <em>JavaScript Object Notation</em>, kurz JSON, für Im- und Exportdateien. JSON wird verwendet, um strukturierte Daten zwischen Anwendungen auszutauschen.</p><p>Dieses Format ist kompakt und noch immer recht gut von Menschen zu lesen und im Bedarfsfall gut zu bearbeiten.</p><p>JSON-Dateien können beliebig verschachtelt werden und enthalten folgende Typen von Elementen:</p><ul><li>Den <strong>Nullwert</strong>, <code>null</code>. Dieser wird wie die Wahrheitswerte unten ohne Anführungszeichen eingetragen.</li><li><strong>Wahrheitswerte:</strong> <code>true</code> bedeutet wahr, <code>false</code> bedeutet falsch. Beide Werte stehen ohne Anführungszeichen.</li><li><strong>Zahlen:</strong> Positive und negative Zahlen werden ohne Anführungszeichen geschrieben, zum Beispiel <code>-42</code> oder <code>3.1415926</code>. Als Dezimaltrennzeichen dient ein Punkt statt des deutschen Kommas.</li><li><strong>Zeichenketten</strong>, diese werden durch doppelte Anführungszeichen &quot; eingeschlossen: <code>&quot;Dies ist ein Satz&quot;</code>.</li><li><strong>Arrays</strong> sind Listen in eckigen Klammern <strong>[</strong> und <strong>]</strong>. Kommas trennen die einzelnen Elemente. Eine leere Liste ist ebenfalls zulässig.</li><li><strong>Objekte</strong> werden durch geschweifte Klammern, <strong>{</strong> und <strong>}</strong>, eingeschlossen und enthalten eine durch Kommata getrennte, ungeordnete Liste von Eigenschaften. <ul><li>Die <strong>Eigenschaften</strong> bestehen aus einem <em>Schlüssel</em>, der eine Zeichenkette ist und dem zugehörigen Wert eines beliebigen Datentyps.</li></ul></li></ul><p>Beispiel: Kataloge ➜ Räume Die json-Datei enthält zum Beispiel die Informationen zu Räumen in folgender Weise:</p><pre><code>  [{&quot;id&quot; : 2,&quot;kuerzel&quot; : &quot;R2&quot;,&quot;beschreibung&quot; : &quot;Ein zweiter Raum&quot;,&quot;groesse&quot; : 1},{&quot;id&quot; : 1,&quot;kuerzel&quot; : &quot;R1&quot;,&quot;beschreibung&quot; : &quot;Ein erster Raum&quot;,&quot;groesse&quot; : 2}]
</code></pre><p>Das gesamte Beispiel ist eine Liste (<strong>Array</strong>) in eckigen Klammern <code>[]</code>. Darin steht jeder Raum als eigenes <strong>Objekt</strong> in geschweiften Klammern <code>{}</code>. Kommas trennen die Räume voneinander.</p><p>Innerhalb eines Eintrags finden sich die Schlüssel mit den jeweils passenden Daten als Werte. Nach einem Doppelpunkt hinter dem Schlüssel : folgt der jeweilige Wert.</p><p>Zahlen werden direkt geschrieben. Text, also Zeichenfolgen, in Anführungszeichen &quot;&quot; eingefasst.</p><p>Jeder neue Eintrag ist ein neues Objekt, die mit einem Komma getrennt werden.</p><p><a href="/bilder/schueler/svws-kataloge-raeume-json.png"><img src="`+s+'" alt="Eine JSON-Datei wird im Editor mit passendem Plugin lesbar angezeigt." loading="lazy"></a></p><p><em>Eine JSON-Datei wird im Editor mit passendem Plugin lesbar angezeigt.</em></p><p>Manche Editoren erlauben das besser lesbare Anzeigen von json-Files:</p><p>Hier im Screenshot wurde das Programm Notepad++ mit dem Plugin JSON Viewer verwendet.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Das_JSON-Dateiformat_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5634.</p>',18)])])}const p=n(o,[["render",a]]);export{m as __pageData,p as default};
